// Feedback + error mapping helpers (generated by engineering-platform frontend-enterprise-management asset)
// Unified success feedback and stable error UX. Pages never use alert() or
// console.log as user feedback; never render Java stacktraces / raw JSON.
import { ElMessage, ElNotification } from 'element-plus';
import { ApiError } from '../api/request';

export function notifySuccess(title: string, message?: string): void {
  ElNotification.success({ title, message: message ?? '', duration: 2500 });
}

export function notifyError(title: string, message?: string): void {
  ElNotification.error({ title, message: message ?? '', duration: 4000 });
}

export function toastSuccess(message: string): void {
  ElMessage.success(message);
}

/** Stable error text for a thrown value (ApiError code/message, network, unknown). */
export function errorText(e: unknown): string {
  if (e instanceof ApiError) {
    return e.message || e.code;
  }
  if (e instanceof Error) {
    return e.message;
  }
  return 'Unexpected error';
}

/** Map a backend error code to a user-facing message (validation/permission/conflict/not-found/network). */
export function errorMessage(e: unknown): string {
  if (e instanceof ApiError) {
    switch (e.status) {
      case 401:
        return 'Your session has expired. Please sign in again.';
      case 403:
        return 'You do not have permission to perform this action.';
      case 404:
        return 'The requested resource was not found.';
      case 409:
        return e.message || 'The resource already exists.';
      case 400:
        return e.message || 'Please check the form and try again.';
      default:
        return e.message || 'The server could not complete the request.';
    }
  }
  if (e instanceof TypeError && e.message.includes('fetch')) {
    return 'Network error — please check your connection.';
  }
  return e instanceof Error ? e.message : 'Unexpected error';
}
